export function calcMonthly(periods){const map=new Map();for(const period of periods){for(let date=period.start;date<=period.end;date=shiftDate(date,1)){const key=date.slice(0,7)+'-'+period.parent,old=map.get(key)||{month:date.slice(0,7),parent:period.parent,dates:new Set(),gross:0,known:true};old.dates.add(date);if(period.daily===null)old.known=false;else old.gross=calcRound(old.gross+period.daily);map.set(key,old);}}return [...map.values()].sort((a,b)=>a.month.localeCompare(b.month)||a.parent-b.parent).map(({dates,...m})=>({...m,days:dates.size,gross:m.known?m.gross:null}));}
